const r = await tools.exec_command({cmd: "@'
$records = Get-Content -LiteralPath 'data/pilot-places.json' -Raw | ConvertFrom-Json
"COUNT $($records.Count)"
foreach ($p in $records) {
  $fields = @('name','category','barangay','address','location','description','services','publicPhone','publicEmail')
  $bad = @()
  foreach ($f in $fields) { if ($null -ne $p.$f -and -not ($p.sources | Where-Object fieldKey -eq $f)) { $bad += $f } }
  $locationSourceTypes = @($p.sources | Where-Object fieldKey -eq 'location' | ForEach-Object sourceType | Sort-Object -Unique) -join ','
  [pscustomobject]@{key=$p.sourceKey;name=$p.name;barangay=$p.barangay;address=$p.address;location=if($p.location){"$($p.location.lat),$($p.location.lng)"}else{''}; sourceCount=$p.sources.Count; unsupported=$bad -join ','; locationSources=$locationSourceTypes; sourceUrls=(@($p.sources.sourceUrl | Sort-Object -Unique) -join ';')}
} | Format-List
'@ | powershell -NoProfile -Command -", workdir: "C:\Users\ckzz2\.codex\worktrees\muntara-pilot\muntara", max_output_tokens: 15000});
text(r.output);

